    private JSTypeRegistry createRegistry() {
        // SemanticReverseAbstractInterpreter requires an ErrorReporter, which Compiler provides.
        // For testing purposes, we can use a dummy ErrorReporter or a mock.
        // The simplest way to get a working JSTypeRegistry is via AbstractCompiler.
        return new JSTypeRegistry(null); // Using null for ErrorReporter for simplicity here.
    }

    private AbstractCompiler createCompiler() {
        return new Compiler();
    }

    private ReverseAbstractInterpreter createReverseInterpreter(AbstractCompiler compiler, JSTypeRegistry registry) {
        return new SemanticReverseAbstractInterpreter(compiler.getCodingConvention(), registry);
    }

    private TypeInference createTypeInference(AbstractCompiler compiler, ControlFlowGraph<Node> cfg, ReverseAbstractInterpreter rai, Scope scope, Map<String, AssertionFunctionSpec> assertionFunctionsMap) {
        return new TypeInference(compiler, cfg, rai, scope, assertionFunctionsMap);
    }

    private Scope createScope(AbstractCompiler compiler, Node root) {
        return new TypedScopeCreator(compiler).createScope(root, null);
    }

    @Test
    public void testTraverseAssign() throws Exception {
        JSTypeRegistry registry = createRegistry();
        AbstractCompiler compiler = createCompiler();
        Node root = new Node(Token.SCRIPT);
        Scope globalScope = createScope(compiler, root);
        ReverseAbstractInterpreter rai = createReverseInterpreter(compiler, registry);
        Map<String, AssertionFunctionSpec> assertionFunctionsMap = Maps.newHashMap();
        TypeInference typeInference = createTypeInference(compiler, new ControlFlowGraph<>(), rai, globalScope, assertionFunctionsMap);

        Node assignNode = new Node(Token.ASSIGN, Node.newString("x"), Node.newNumber(5));
        assignNode.getFirstChild().setJSType(registry.getNativeType(JSTypeNative.NUMBER_TYPE)); // Use getNativeType
        assignNode.getLastChild().setJSType(registry.getNativeType(JSTypeNative.NUMBER_TYPE)); // Use getNativeType

        FlowScope initialScope = LinkedFlowScope.createEntryLattice(globalScope);
        FlowScope resultScope = typeInference.flowThrough(assignNode, initialScope);

        assertNotNull(assignNode.getJSType());
        assertEquals(registry.getNativeType(JSTypeNative.NUMBER_TYPE), assignNode.getJSType()); // Use getNativeType

        Var varX = globalScope.getVar("x");
        assertNotNull(varX);
        assertEquals(registry.getNativeType(JSTypeNative.NUMBER_TYPE), varX.getType()); // Use getNativeType
    }

